from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];script=json.loads((R/'src/data/script.json').read_text());board=json.loads((R/'src/data/storyboard.json').read_text());demo=json.loads((R/'src/data/demo-map.json').read_text());rows=[];samples=18*48000
lines=['# Frame-addressed motion blueprint','','30 fps; 3840×1920; all frame ranges are **zero-based and half-open**. Global frame = section start + local frame. Audio uses exact 48 kHz sample positions; picture cue rounding is at most half a frame.','','## Timing','','| Recording | Decoded seconds | Start time | Global frames |','|---|---:|---:|---:|']
for s in script:
 start=round(samples/48000*30);end=round((samples+s['samples'])/48000*30);s['globalStart']=start;s['globalEnd']=end
 lines.append(f"| {s['id']} | {s['samples']/48000:.6f} | {samples/48000:.6f} s | [{start}, {end}) |")
 samples+=s['samples']
lines+=['','Opening: [0,540). References: [13578,13818). Full picture length: **460.600 seconds**.','','## Camera poses','','| Pose | Camera XYZ | Look-at XYZ |','|---|---|---|','| N | 0,0,2400 | 0,0,0 |','| H | 0,0,2240 | 0,100,80 |','| W | 0,0,2680 | 0,0,0 |','| L | -120,25,2340 | -360,0,100 |','| R | 120,25,2340 | 360,0,100 |','| G | 0,75,2360 | 0,80,120 |','| A | 0,0,2540 | 0,0,0 |','','For an A→B camera sweep, use cubic spatial controls P1=A+(B−A)/3+bulge and P2=A+2(B−A)/3+bulge. Bulge X=40×sign(Bx−Ax), Y=−12×sign(Bx−Ax), Z=0. Time ease is cubic Bezier (0.42,0,0.58,1). Target interpolates with the same eased progress. Hold the destination for the rest of the beat; the last 18 section frames return toward N.','','## Shared layer and typography rules','','- The primary plate is projected through a real 2400-unit pinhole camera and an eight-parameter homography.','- Source viewport: crop x=352,y=0,w=2320,h=1582 from the original 3024×1582 capture. Preserve source pixels, cursor and recorded numbers.','- Video enters over 24 frames: opacity .3→1, Y −180→0, Z −180→120, X tilt 7→0°, Y tilt −9→0°. Ease-out (0.16,1,0.3,1).','- Main glass is a separate frosted/rim material; no blur is applied to the recording. A reading-safe projected containment rectangle prevents camera sweeps from cropping controls.','- Narrative panels use Z=160, 4° X / −6° Y tilt, 24-frame elevation/opacity reveal.','- Headline: Inter 650, 112 design pixels (57 on demo sidebars), tracking −.035em, warm white. Word reveal is 10 frames, 3-frame stagger, Y +24→0. Default delay is 12 frames.','- Eyebrow: Inter 600, 32 px, uppercase, +.12em tracking. Captions: 54 px, 1.27 line height, screen-space bottom-safe area.','- Avatar motion uses per-recording librosa RMS/band data. Hero motion is 2% amplitude scale plus .6% low-band scale, low-band lift, mid-band glow/rotation, gated high-band onset particles. Reading mode uses 35% motion and zero particles.','- At a new beat, cards fade/lift in over 24 frames and the camera follows the specified sweep. Numeric results fade in without inventing intermediate count-up values.','- Hybrid, focus, accessibility and privacy diagrams are labelled as proposed/untested, reported observations, or future conditional flows as appropriate.','','## Every narrated beat']
for s in script:
 lines += ['',f"### {s['id']} — {s['speaker']}",'','| Local frames | Global frames | Camera / sweep | Visual layer | Exact editorial copy | Audio reactivity |','|---|---|---|---|---|---|']
 for b in board[s['id']]:
  txt=b['headline']+' / '+' / '.join(b['lines']);txt=txt.replace('|','\\|');mode='Reading: 35%, no particles' if b['kind']=='demo' else 'Hero: waveform scale/glow; gated particles'
  extra=f"; headline delay {b['textDelay']}f" if 'textDelay'in b else '';extra+=f"; line delay {b['linesDelay']}f" if 'linesDelay'in b else ''
  lines.append(f"| [{b['start']},{b['end']}) | [{s['globalStart']+b['start']},{s['globalStart']+b['end']}) | {'→'.join(b['camera'])}, {b['sweep']}f | {b['kind']}{extra} | {txt} | {mode} |")
lines+=['','## Exact recorded-source conform','','Each moving interval retimes only the recorded source PTS range. Each hold repeats one native recorded frame. The UI content is never AI-generated. Timer values remain their original values; playback retiming is disclosed.']
for key,m in demo.items():
 lines+=['',f'### {key} — {m["source"]}','','| Output local frames | Source operation |','|---|---|']
 for p in m['pieces']:
  op=f"Play PTS {p['sourceStart']:.6f}→{p['sourceEnd']:.6f} s" if 'sourceStart'in p else f"Hold native source frame {p['holdFrame']}" if 'holdFrame'in p else f"Hold first decoded frame at/after PTS {p['holdTime']} s"
  lines.append(f"| [{p['from']},{p['to']}) | {op} |")
lines+=['','The Raj-03 conform removes inactive time between the two-error state and the later correction. It preserves the recorded state order. The required date, course-code typo and timer outcomes are not changed.','','## Opening and references','','Opening [0,90): “A conversation.”; [90,240): “Confirmed.”; [240,420): “But is it correct?”; [420,540): “Chat or form?”. Glass check/lens visual, slow dolly, subtle procedural sound bed, no added synthetic narrator.','','References [13578,13698): first four references; [13698,13818): remaining references and production notes. Final 18 frames fade toward obsidian.']
(R/'docs/MOTION-BLUEPRINT.md').write_text('\n'.join(lines)+'\n')
print('Exported exact timing, camera rules, all 54 narrated beats and source conform tables.')
